package com.bank.transfer.service;

import com.bank.transfer.model.Account;
import com.bank.transfer.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
@Slf4j
@RequiredArgsConstructor
public class TransferService {

    private final AccountRepository accountRepo;

    // Core business operation — kept stateless so any Pod can serve any request.
    @Transactional
    public void transfer(String fromId, String toId, BigDecimal rentAmount) {
        Account rajesh = accountRepo.findById(fromId)
                .orElseThrow(() -> new IllegalArgumentException("No account " + fromId));
        Account priya = accountRepo.findById(toId)
                .orElseThrow(() -> new IllegalArgumentException("No account " + toId));

        rajesh.debit(rentAmount);   // balance check lives inside debit()
        priya.credit(rentAmount);
        accountRepo.save(rajesh);
        accountRepo.save(priya);

        log.info("Transfer {} from {} to {} completed", rentAmount, fromId, toId);
    }
}
