// ─── File: src/main/java/com/bank/transfer/model/Account.java ───
package com.bank.transfer.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id private String id;
    private String holderName;
    private BigDecimal balance;

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient balance in " + id);
        this.balance = balance.subtract(amount);
    }
    public void credit(BigDecimal amount) { this.balance = balance.add(amount); }

    public String getId() { return id; }
    public BigDecimal getBalance() { return balance; }
}
