# ─── File: Dockerfile ───  multi-stage: build with JDK, run on slim JRE
# ----- build stage -----
FROM maven:3.9-eclipse-temurin-21 AS build
WORKDIR /app
COPY pom.xml .
RUN mvn -q dependency:go-offline        # cache dependencies for faster rebuilds
COPY src ./src
RUN mvn -q clean package -DskipTests    # produces target/transfer-service.jar

# ----- runtime stage -----
FROM eclipse-temurin:21-jre-alpine
WORKDIR /app
RUN addgroup -S bank && adduser -S bank -G bank
COPY --from=build /app/target/transfer-service.jar app.jar
USER bank                                # never run as root
EXPOSE 8080
# size the heap to the container memory limit so the JVM is not OOM-killed
ENTRYPOINT ["java","-XX:MaxRAMPercentage=75.0","-jar","/app.jar"]
