# ─── File: k8s/deployment.yaml ───  production: 3 replicas, probes, resources
apiVersion: apps/v1
kind: Deployment
metadata:
  name: transfer-service
spec:
  replicas: 3                            # desired state: keep 3 Pods alive
  selector:
    matchLabels: { app: transfer-service }
  strategy:
    rollingUpdate: { maxSurge: 1, maxUnavailable: 0 }   # zero-downtime rollout
  template:
    metadata:
      labels: { app: transfer-service }
    spec:
      containers:
        - name: transfer-service
          image: registry.bank.in/transfer-service:1.4.0   # immutable, versioned
          ports: [{ containerPort: 8080 }]
          env:
            - name: DB_PASSWORD
              valueFrom: { secretKeyRef: { name: db-secret, key: password } }
          resources:
            requests: { cpu: "250m", memory: "512Mi" }
            limits:   { cpu: "1",    memory: "768Mi" }
          readinessProbe:
            httpGet: { path: /actuator/health/readiness, port: 8080 }
            initialDelaySeconds: 10
          livenessProbe:
            httpGet: { path: /actuator/health/liveness, port: 8080 }
            initialDelaySeconds: 30
